import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** A template field line whose value was never filled in, e.g. `- **Retention**:` */
const EMPTY_FIELD = /^\s*[-*]\s*\*\*[^*]+\*\*.*:\s*$/;

interface Section {
  heading: string;
  body: string;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const fieldLine = body
    .split(/\r?\n/)
    .find((l) => /\*\*tier\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l));
  const haystacks = fieldLine ? [fieldLine] : [body];
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

function answeredText(body: string): string {
  return body
    .split(/\r?\n/)
    .filter((l) => !EMPTY_FIELD.test(l))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const answered = answeredText(body);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const emptyFields = body.split(/\r?\n/).filter((l) => EMPTY_FIELD.test(l));
    for (const line of emptyFields) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffLine = body
          .split(/\r?\n/)
          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}
export type Severity = 'block' | 'warn';

export interface GateCheck {
  id: string;
  title: string;
  /** Matches the subsection heading inside the Responsible AI Gate section. */
  headingPattern: RegExp;
  /** When true, a body without any digit produces a warning (thresholds expected). */
  expectsNumbers?: boolean;
}

/** Matches both the branded "FRAI Gate" heading and the long-form "Responsible AI Gate". */
export const GATE_HEADING = /(responsible\s+ai|frai)\s+gate/i;

export const RISK_TIERS = ['prohibited', 'high', 'limited', 'minimal'] as const;
export type RiskTier = (typeof RISK_TIERS)[number];

export const GATE_CHECKS: GateCheck[] = [
  { id: 'risk-tier', title: 'Risk tier', headingPattern: /risk|tier/i },
  {
    id: 'data-privacy',
    title: 'Data & privacy',
    headingPattern: /data|privacy|provenance/i
  },
  { id: 'oversight', title: 'Human oversight', headingPattern: /oversight|human|control/i },
  {
    id: 'evaluation',
    title: 'Evaluation plan',
    headingPattern: /eval/i,
    expectsNumbers: true
  },
  { id: 'bias', title: 'Bias & fairness', headingPattern: /bias|fairness/i },
  {
    id: 'monitoring',
    title: 'Monitoring & rollback',
    headingPattern: /monitor|rollback/i,
    expectsNumbers: true
  },
  {
    id: 'transparency',
    title: 'Transparency & incidents',
    headingPattern: /transparen|incident|disclosure/i
  }
];

export interface Finding {
  checkId: string;
  severity: Severity;
  message: string;
  /** 'validator' for deterministic findings, 'agent' for smart-review findings. */
  source: 'validator' | 'agent';
}

export type Verdict = 'PASS' | 'WARN' | 'BLOCK';

export interface GateResult {
  verdict: Verdict;
  tier: RiskTier | null;
  findings: Finding[];
  /** Raw text of the gate section, when found. */
  gateSection: string | null;
}

export function verdictFrom(findings: Finding[]): Verdict {
  if (findings.some((f) => f.severity === 'block')) return 'BLOCK';
  if (findings.some((f) => f.severity === 'warn')) return 'WARN';
  return 'PASS';
}
import { Finding, GateResult } from './schema.js';

const VERDICT_ICON: Record<GateResult['verdict'], string> = {
  PASS: '✅',
  WARN: '⚠️',
  BLOCK: '⛔'
};

function line(finding: Finding): string {
  const icon = finding.severity === 'block' ? '⛔' : '⚠️';
  const tag = finding.source === 'agent' ? ' (smart review)' : '';
  return `${icon} [${finding.checkId}]${tag} ${finding.message}`;
}

export function renderText(result: GateResult, specPath: string): string {
  const out: string[] = [];
  out.push(`FRAI Gate - ${specPath}`);
  out.push(`Verdict: ${VERDICT_ICON[result.verdict]} ${result.verdict}`);
  if (result.tier) out.push(`Risk tier: ${result.tier}`);
  if (result.findings.length === 0) {
    out.push('All seven gate checks answered. Clear to implement.');
  } else {
    out.push('');
    for (const finding of result.findings) out.push(line(finding));
    out.push('');
    if (result.verdict === 'BLOCK') {
      out.push('BLOCK: fix the items above before implementation starts.');
    } else if (result.verdict === 'WARN') {
      out.push('WARN: the gate passes structurally, but tighten the flagged answers.');
    }
  }
  return out.join('\n');
}

export function renderJson(result: GateResult, specPath: string): string {
  return JSON.stringify(
    {
      spec: specPath,
      verdict: result.verdict,
      tier: result.tier,
      findings: result.findings
    },
    null,
    2
  );
}

