import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** The marker `frai-gate draft` leaves wherever only a human can supply the answer. */
const NEEDS_HUMAN_INPUT = /\bNEEDS\s+HUMAN\s+INPUT\b/;
/**
 * A field label with nothing after it on the same line, in either style:
 * `- **Retention**:` / `- **Retention** (hint):` or `- **Retention:**`.
 * The answer may still sit on indented lines below - see isEmptyField.
 */
const BARE_LABEL = [/^\s*[-*]\s*\*\*[^*]+\*\*.*:\s*$/, /^\s*[-*]\s*\*\*[^*]+:\*\*\s*$/];
const SIGNOFF = /sign[- ]?off/i;

function isBareLabel(line: string): boolean {
  return BARE_LABEL.some((re) => re.test(line));
}

function indentOf(line: string): number {
  return (line.match(/^[ \t]*/)?.[0] ?? '').replace(/\t/g, '    ').length;
}

/** The indented lines below lines[index] (nested bullets, tables, paragraphs), blank lines in between allowed. */
function continuation(lines: string[], index: number): string[] {
  const indent = indentOf(lines[index]);
  const block: string[] = [];
  for (const line of lines.slice(index + 1)) {
    if (line.trim() === '') {
      block.push(line);
      continue;
    }
    if (indentOf(line) <= indent) break;
    block.push(line);
  }
  while (block.length > 0 && block[block.length - 1].trim() === '') block.pop();
  return block;
}

/** A field label with no answer: nothing after it on its line and nothing indented below it. */
function isEmptyField(lines: string[], index: number): boolean {
  return isBareLabel(lines[index]) && continuation(lines, index).length === 0;
}

function emptyFieldLines(body: string): string[] {
  const lines = body.split(/\r?\n/);
  return lines.filter((_, i) => isEmptyField(lines, i));
}

interface Section {
  heading: string;
  body: string;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const lines = body.split(/\r?\n/);
  const fieldIndex = lines.findIndex(
    (l) => /\*\*tier:?\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l)
  );
  let haystacks: string[];
  if (fieldIndex === -1) {
    haystacks = [body];
  } else if (!isBareLabel(lines[fieldIndex])) {
    haystacks = [lines[fieldIndex]];
  } else {
    // The value sits below the label; if that block names several tiers, its first line decides.
    const block = continuation(lines, fieldIndex).filter((l) => l.trim() !== '');
    haystacks = block.length > 0 ? [block.join('\n'), block[0]] : [];
  }
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

function extractSignoff(body: string): string {
  const lines = body.split(/\r?\n/);
  // Prefer the Sign-off field itself over other lines that merely mention sign-off.
  let index = lines.findIndex((l) => /^\s*[-*]\s*\*\*[^*]*sign[- ]?off[^*]*\*\*/i.test(l));
  if (index === -1 || isEmptyField(lines, index)) {
    index = lines.findIndex((l, i) => SIGNOFF.test(l) && !isEmptyField(lines, i));
  }
  if (index === -1) return '';
  if (isBareLabel(lines[index])) return continuation(lines, index).join('\n').trim();
  return lines[index].split(':').slice(1).join(':').trim();
}

function answeredText(body: string): string {
  const lines = body.split(/\r?\n/);
  return lines
    .filter((_, i) => !isEmptyField(lines, i))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const answered = answeredText(body);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const humanInputs = body.split(/\r?\n/).filter((l) => NEEDS_HUMAN_INPUT.test(l)).length;
    if (humanInputs > 0) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" has ${humanInputs} unresolved NEEDS HUMAN INPUT item${humanInputs === 1 ? '' : 's'}. Answer each one and remove the marker.`,
        source: 'validator'
      });
    }
    const emptyFields = emptyFieldLines(body);
    for (const line of emptyFields) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffValue = extractSignoff(body);
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

