import fs from 'node:fs';
import { spawnSync } from 'node:child_process';
const { validateSpec: oldV } = await import('./dist/gate/old-validate.tmp.js');
const { validateSpec: newV } = await import('./dist/gate/validate.js');
for (const f of [
  'assets/rai-spec-template.md',
  '../../examples/frai-spec-example.md',
  '../../examples/support-triage-demo/FRAI-SPEC.md',
  '../../examples/support-triage-demo/rai-gate-draft.reference.md'
]) {
  const md = fs.readFileSync(f, 'utf8');
  const a = oldV(md);
  const b = newV(md);
  const gate = spawnSync(process.execPath, ['dist/cli.js', 'check', f, '--json']).status;
  const frai = spawnSync(process.execPath, ['../frai-cli/dist/index.js', 'gate', 'check', f]).status;
  console.log(f, JSON.stringify(a) === JSON.stringify(b) ? 'IDENTICAL' : 'DIFFERENT', b.verdict, b.tier, b.findings.length, `exit frai-gate=${gate} frai=${frai}`);
}

